// План specs/job-assignment.md 1.1–1.5 (кейсы .qa/tests/job-assignment/JA-01…JA-05). Admin, компания «test», десктоп, EN.
// @writes: назначает/снимает QA-Tech Alpha/Beta на работе «QA-AUTO 04d33a job» (создаётся один раз, дальше переиспользуется).
// В конце прогона работа остаётся в Submitted без техника (afterAll). «Allow Multiple Techs» только читается:
// если ON — тесты пропускаются, настройку НЕ переключаем. Техники без согласия на SMS → в истории «No SMS», SMS не уходят.
import { test, expect } from '@playwright/test';
import { cellValue } from '../admin-plans/plans-read-helpers';
import { ADMIN_STATE, adminContext, prepare, readMultiTech } from '../multi-tech-assignment/multi-tech-helpers';
import {
  ALPHA, BETA,
  acceptLeaveDialogs, assignTech, ensureNoTechnician, expectLatestHistory, expectNoTechnician, expectStatus,
  expectTechnician, jobRow, latestHistoryEntry, openJobsTab, openQaJob, takeOffButton,
} from './assignment-helpers';

test.use({ storageState: ADMIN_STATE });
test.describe.configure({ mode: 'serial' });

test.describe('Job assignment: take a technician off the job with Allow Multiple Techs OFF (#04d33a)', () => {
  let multiOn: boolean | undefined;
  let jobUrl = '';
  let jobId = '';

  test.beforeAll(async ({ browser }, testInfo) => {
    test.setTimeout(180_000);
    const { context, page } = await adminContext(browser, testInfo);
    try {
      multiOn = await readMultiTech(page);
      if (multiOn) return;
      acceptLeaveDialogs(page);
      ({ url: jobUrl, jobId } = await openQaJob(page));
      // Исходное состояние: без техника, Submitted.
      await page.goto(jobUrl);
      await ensureNoTechnician(page);
      await expectStatus(page, 'Submitted');
    } finally {
      await context.close();
    }
  });

  test.beforeEach(async ({ page }) => {
    test.skip(multiOn !== false, '«Allow Multiple Techs» = ON (или не прочитана) — сценарий только для OFF; настройку не переключаем');
    test.setTimeout(120_000);
    await prepare(page, 'en');
    acceptLeaveDialogs(page);
  });

  // Работа остаётся без техника (Submitted), даже если тест упал посередине.
  test.afterAll(async ({ browser }, testInfo) => {
    if (multiOn !== false || !jobUrl) return;
    const { context, page } = await adminContext(browser, testInfo);
    try {
      acceptLeaveDialogs(page);
      await page.goto(jobUrl);
      await ensureNoTechnician(page);
    } finally {
      await context.close();
    }
  });

  test('Assign Technician on the job page: status Assigned, history "Assigned to QA-Tech Alpha" with No SMS and Send again, X button next to the field #04d33a @desktop @writes', async ({ page }) => {
    await page.goto(jobUrl);
    await expectNoTechnician(page);

    await assignTech(page, ALPHA);

    // Источник: DoD «השיבוץ … משנה סטטוס ל'שובצה'»; «כשל התראה אינו מבטל שיבוץ; ניתן לשלוח שוב».
    await expectLatestHistory(page, `Assigned to ${ALPHA}`);
    await expectTechnician(page, ALPHA);
    await expectStatus(page, 'Assigned');
    const entry = latestHistoryEntry(page);
    await expect(entry.getByText('No SMS', { exact: true })).toBeVisible({ timeout: 60_000 });
    await expect(entry.getByRole('button', { name: 'Send again' })).toBeVisible();
  });

  test('X takes the technician off the job: field "Select technician", status Submitted, history "taken off the job", after reload the technician does not come back and X is hidden #04d33a @desktop @writes', async ({ page }) => {
    await page.goto(jobUrl);
    await expectTechnician(page, ALPHA);

    await takeOffButton(page, ALPHA).click();

    // Источник: «מצב רצוי» реджекта 2 — העבודה בלי טכנאי, הסטטוס חוזר ל-Submitted, בהיסטוריה שורה על ההסרה.
    await expectNoTechnician(page);
    await expectStatus(page, 'Submitted');
    await expectLatestHistory(page, `${ALPHA} taken off the job`);

    // Сохранено на сервере: после перезагрузки техник не вернулся, X нет.
    await page.reload();
    await expectLatestHistory(page, `${ALPHA} taken off the job`);
    await expectNoTechnician(page);
    await expectStatus(page, 'Submitted');
  });

  test('Jobs list: the job without a technician is in Submitted with Technician "Unassigned" and not in Assigned #04d33a @desktop @writes', async ({ page }) => {
    // Источник: «מצב רצוי» реджекта 2 — העבודה בלי טכנאי ("Unassigned"), הסטטוס חוזר ל-Submitted.
    await openJobsTab(page, 'Submitted');
    await page.getByPlaceholder(/^Search jobs/i).fill(jobId);
    await expect(jobRow(page, jobId)).toBeVisible({ timeout: 20_000 });
    expect(await cellValue(page, jobRow(page, jobId), 'Technician'), `Technician у ${jobId}`).toBe('Unassigned');

    await page.getByRole('tab', { name: 'Assigned', exact: true }).click();
    await expect(page.getByRole('tab', { name: 'Assigned', exact: true })).toHaveAttribute('aria-selected', 'true');
    await expect(jobRow(page, jobId)).toHaveCount(0);
  });

  test('Replacing the technician from the list writes "Reassigned from QA-Tech Alpha to QA-Tech Beta"; X then takes QA-Tech Beta off #04d33a @desktop @writes', async ({ page }) => {
    await page.goto(jobUrl);
    await expectNoTechnician(page);

    await assignTech(page, ALPHA);
    await expectLatestHistory(page, `Assigned to ${ALPHA}`);

    // Источник: AC «שיבוץ מחדש מעביר את העבודה»; DoD «ניתן לבטל/לשבץ מחדש, וההיסטוריה נשמרת».
    await assignTech(page, BETA);
    await expectLatestHistory(page, `Reassigned from ${ALPHA} to ${BETA}`);
    await expectTechnician(page, BETA);
    await expect(takeOffButton(page, ALPHA)).toHaveCount(0);
    await expectStatus(page, 'Assigned');

    await takeOffButton(page, BETA).click();
    await expectLatestHistory(page, `${BETA} taken off the job`);
    await expectNoTechnician(page);
    await expectStatus(page, 'Submitted');
  });

  test('Leaving through the Jobs menu right after X keeps the technician taken off #04d33a @desktop @writes', async ({ page }) => {
    await page.goto(jobUrl);
    await expectNoTechnician(page);
    await assignTech(page, ALPHA);
    await expectLatestHistory(page, `Assigned to ${ALPHA}`);
    await expectTechnician(page, ALPHA);

    // X и сразу уход через боковое меню — без ожидания автосохранения (#550b46).
    await takeOffButton(page, ALPHA).click();
    await page.getByRole('link', { name: 'Jobs', exact: true }).first().click();
    await page.waitForURL(/\/jobs/i);

    // Источник: «מצב רצוי» реджекта 2; #550b46 — изменение назначения не теряется при уходе до автосохранения.
    // Список Jobs здесь не проверяем: после быстрого ухода он может показывать устаревшего техника (находка 12.11, не реджект).
    await page.goto(jobUrl);
    await expectLatestHistory(page, `${ALPHA} taken off the job`);
    await expectNoTechnician(page);
    await expectStatus(page, 'Submitted');
  });
});
